Method.Source:
/// <summary>
///    Creates a record for each range in a query.
/// </summary>
/// <param name="_queryPacked">
///    A packed query.
/// </param>
/// <param name="_tmpConditon">
///    A temporary table that is used to hold the ranges.
/// </param>
public static void stageFulfilmentConditionTmp(container _queryPacked, METFulfilmentConditionTmp _tmpConditon)
{
    Query conditon;
    int dsN;
    int dsI;

    void addFilter(Query _query)
    {
        int nFilter = _query.queryFilterCount();
        int iFilter;

        for (iFilter = 1; iFilter <= nFilter; iFilter++)
        {
            QueryFilter qf = _query.queryFilter(iFilter);

            if (qf.value() && qf.status() != RangeStatus::Hidden)
            {
                QueryBuildDataSource qbds = qf.dataSource();
                TableId tableId = qbds.table();
                FieldId fieldId = fieldName2Id(tableId, qf.field());

                _tmpConditon.clear();
                _tmpConditon.Table = tableid2pname(tableId);
                _tmpConditon.Field = fieldid2pname(tableId, fieldId);
                _tmpConditon.Value = qf.value();
                _tmpConditon.insert();
            }
        }
    }

    void addRange(QueryBuildRange _range)
    {
        if (_range.value() && _range.status() != RangeStatus::Hidden)
        {
            _tmpConditon.clear();
            _tmpConditon.Table = tableid2pname(_range.table());
            _tmpConditon.Field = fieldid2pname(_range.table(), _range.field());
            _tmpConditon.Value = _range.value();
            _tmpConditon.insert();
        }
    }

    void addDatasource(QueryBuildDataSource _ds)
    {
        int nRange = _ds.rangeCount();
        int iRange;
        for (iRange = 1; iRange <= nRange; iRange++)
        {
            addRange(_ds.range(iRange));
        }
    }

    delete_from _tmpConditon;

    if (conlen(_queryPacked) > 0)
    {
        conditon = new Query(_queryPacked);
        dsN = conditon.dataSourceCount();
        for (dsI = 1; dsI <= dsN; dsI++)
        {
            addDatasource(conditon.dataSourceNo(dsI));
        }

        addFilter(conditon);
    }
}
